insert into change_headers (id, ts) values (70, '2026-10-29') on duplicate key update ts = values(ts);
insert into change_descriptions (id, lang, description) values (70, 'ru', 'Торговый калькулятор теперь считает и в обратную сторону: укажите, сколько ресурсов хотите получить, и он покажет, сколько нужно продать (с округлением вверх). Направление переключается кнопками над панелями или щелчком по стрелке между ними.') on duplicate key update description = values(description);
insert into change_descriptions (id, lang, description) values (70, 'en', 'The Trade calculator now also works the other way round: enter how many resources you want to receive, and it shows how much you need to sell (rounded up). Switch the direction with the buttons above the panels or by clicking the arrow between them.') on duplicate key update description = values(description);
insert into change_descriptions (id, lang, description) values (70, 'pt', 'A Calculadora de Troca agora também funciona no sentido inverso: indica quantos recursos queres receber e ela mostra quanto precisas de vender (arredondado para cima). A direção muda com os botões acima dos painéis ou com um clique na seta entre eles.') on duplicate key update description = values(description);
insert into change_descriptions (id, lang, description) values (70, 'de', 'Der Handelsrechner rechnet jetzt auch in die umgekehrte Richtung: Gib an, wie viele Rohstoffe du erhalten willst, und er zeigt, wie viel du verkaufen musst (aufgerundet). Die Richtung wechselst du mit den Schaltern über den Feldern oder per Klick auf den Pfeil dazwischen.') on duplicate key update description = values(description);
insert into change_descriptions (id, lang, description) values (70, 'pl', 'Kalkulator handlu liczy teraz także w drugą stronę: podaj, ile surowców chcesz otrzymać, a pokaże, ile trzeba sprzedać (z zaokrągleniem w górę). Kierunek przełącza się przyciskami nad panelami lub kliknięciem strzałki między nimi.') on duplicate key update description = values(description);
insert into change_descriptions (id, lang, description) values (70, 'es', 'La Calculadora de Comercio ahora también calcula en sentido inverso: indica cuántos recursos quieres recibir y te muestra cuánto necesitas vender (redondeado hacia arriba). La dirección se cambia con los botones sobre los paneles o haciendo clic en la flecha entre ellos.') on duplicate key update description = values(description);
insert into change_descriptions (id, lang, description) values (70, 'fr', 'Le Calculateur de commerce fonctionne désormais aussi dans l''autre sens : indiquez combien de ressources vous voulez recevoir, et il affiche combien il faut vendre (arrondi au supérieur). Le sens se change avec les boutons au-dessus des panneaux ou d''un clic sur la flèche entre eux.') on duplicate key update description = values(description);
insert into change_descriptions (id, lang, description) values (70, 'it', 'Il Calcolatore di Rapporti Commercio ora calcola anche al contrario: indica quante risorse vuoi ricevere e ti mostra quanto devi vendere (arrotondato per eccesso). La direzione si cambia con i pulsanti sopra i pannelli o con un clic sulla freccia tra di essi.') on duplicate key update description = values(description);
insert into change_descriptions (id, lang, description) values (70, 'nl', 'De Handelberekening rekent nu ook andersom: geef op hoeveel grondstoffen je wilt ontvangen, en hij toont hoeveel je moet verkopen (naar boven afgerond). Wissel van richting met de knoppen boven de panelen of door op de pijl ertussen te klikken.') on duplicate key update description = values(description);
insert into change_descriptions (id, lang, description) values (70, 'sk', 'Kalkulátor pre obchody teraz počíta aj opačným smerom: zadaj, koľko surovín chceš dostať, a ukáže, koľko treba predať (zaokrúhlené nahor). Smer sa prepína tlačidlami nad panelmi alebo kliknutím na šípku medzi nimi.') on duplicate key update description = values(description);
insert into change_descriptions (id, lang, description) values (70, 'tr', 'Ticaret Hesaplayıcı artık ters yönde de hesaplıyor: almak istediğiniz kaynak miktarını girin, ne kadar satmanız gerektiğini (yukarı yuvarlanmış olarak) göstersin. Yön, panellerin üstündeki düğmelerle ya da aradaki oka tıklanarak değiştirilir.') on duplicate key update description = values(description);
insert into change_descriptions (id, lang, description) values (70, 'bs', 'Kalkulator trgovine sada računa i u obrnutom smjeru: unesite koliko resursa želite dobiti, a on će pokazati koliko trebate prodati (zaokruženo naviše). Smjer se mijenja dugmadima iznad panela ili klikom na strelicu između njih.') on duplicate key update description = values(description);
